package com.rapidresolve;
import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import org.mindrot.jbcrypt.BCrypt;
@WebServlet("/login") public class LoginServlet extends HttpServlet { protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String e=r.getParameter("email"),p=r.getParameter("password"); try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement("SELECT id,name,password,role FROM users WHERE email=?")){q.setString(1,e);ResultSet x=q.executeQuery();if(x.next()&&BCrypt.checkpw(p,x.getString("password"))){HttpSession h=r.getSession();h.setAttribute("userId",x.getInt("id"));h.setAttribute("userName",x.getString("name"));h.setAttribute("role",x.getString("role"));s.sendRedirect("dashboard.jsp");}else s.sendRedirect("login.html?error=invalid");}catch(Exception x){x.printStackTrace();s.sendRedirect("login.html?error=database");}}}
